mapper.select:
SELECT id, user_id, role, content, created_at
FROM conversation
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT id, user_id, role, content, created_at
FROM conversation
WHERE user_id = #{userId}
  AND created_at >= #{date}
  AND created_at < #{date} + INTERVAL 1 DAY
ORDER BY id
